from mechanism_design_context import add
add('fava',16,'N','FACT','T','P','supported','consistent','none_identified',[( 'incorrectly lists China as an asset location','target','assets in Russia, Kazakhstan, Burkina Faso, Guinea and Canada','Location correction follows references.'),('subjective, unverifiable claim','target','most environmentally conscious mining company in the world','Unsupported superlative matches taxonomy.')],'Identifies target-only unsupported claims and asset substitution; no explicit neighbour use.')
add('fava',17,'S','FACT','R','P','supported','consistent','none_identified',[( 'subjective assertions presented as facts','target','depicts a compelling story that captivates audiences','Explicit evaluative audience assertion falls under supplied taxonomy.'),('reference example also contains subjective assertions','neighbor','truly a masterpiece','Neighbour contains analogous evaluative wording.')],'Explicit analogy grounded in the subjective-assertion criterion. Festival selection does support some recognition, so that subsidiary objection is weaker.')
add('fava',18,'N','FACT','T','P','misreads_text','consistent','unsupported_target_inference',[( 'but not a police detective','target','Kate Lockley is a young police detective working for the LAPD','Supplied source expressly uses the phrase denied by rationale.'),('inaccurately describes her as being "initially unaware of the supernatural"','target','initially unaware of the supernatural','Again a source phrase is treated as false, and is not the target phrasing.')],'Invents distinctions between LAPD detective and police detective, confuses source wording with target claims, and infers a causal attribution to the actress that the target does not state.')
add('fava',19,'N','FACT','T','P','misreads_text','wrong_object','imports_neighbour_facts_or_intent,neighbour_substitutes_for_source_check',[( 'release year as 2015 instead of 2017','neighbor','"Along with the Gods: The Two Worlds" is a South Korean film released in 2015.','The evaluated film and incorrect date are from neighbour.'),('falsely claims the film "does not feature" the listed actors','target','The King and the Clown','Actual target concerns a different film and has no denied-cast claim.')],'Entire rationale evaluates neighbour errors; it never checks actual target cancellation wording. A childhood dream and webtoon adaptation could coexist, so that subsidiary contrast is also not a contradiction by itself.')
